import os, re, json

d = os.environ['RLM_SESSION_DIR']
all_j = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

# Load session as JSON lines
lines = all_j.split('\n')
user_msgs = []
for line in lines:
    if line.startswith('{"type":"message"):'):
        try:
            m = json.loads(line.replace('\\n', '\n').replace('\"message\":{\"role':'"'))
            user_msgs.append((m.get('timestamp', ''), m))
        except:
            pass

# Find the message from user role
for ts, msg in user_msgs:
    if msg.get('role') == 'user':
        content = msg.get('content', [])
        for item in content:
            if isinstance(item, dict) and item.get('type') == 'text':
                text = item.get('text', '')
                if 'task-67dd046a' in text or 'Test input' in text:
                    print("Found first user message with the task:")
                    print(text[:1000])
                    break
